const marketplaceStyle=document.createElement('link');marketplaceStyle.rel='stylesheet';marketplaceStyle.href='marketplace.css?v=20260614-jobs1';document.head.appendChild(marketplaceStyle);
const calendarButton=document.querySelector('[data-view="calendar"]'),notificationButton=document.createElement('button');notificationButton.type='button';notificationButton.dataset.view='notifications';notificationButton.innerHTML='<span class="material-symbols-outlined nav-icon" aria-hidden="true">notifications</span><span class="nav-text" data-short="Alerts">Notifications</span> <span id="notificationCount"></span>';calendarButton.before(notificationButton);
const notificationsView=document.createElement('section');notificationsView.className='dashboard-view';notificationsView.id='notificationsView';notificationsView.hidden=true;notificationsView.innerHTML='<div class="card-heading page-heading"><div><span class="kicker">Activity center</span><h2>Notifications</h2><p>Matching jobs, awards, schedule changes, completions, and verified reviews.</p></div><button class="button button-outline" id="readAllNotifications" type="button">Mark all read</button></div><div class="notification-list" id="notificationList"></div>';document.getElementById('calendarView').before(notificationsView);
const jobFilters=document.getElementById('jobFilters'),radiusLabel=document.createElement('label');radiusLabel.innerHTML='<span>Radius</span><select id="jobRadiusFilter"><option value="25">25 miles</option><option value="50">50 miles</option><option value="75">75 miles</option><option value="100">100 miles</option><option value="150">150 miles</option><option value="250">250 miles</option></select>';jobFilters.insertBefore(radiusLabel,document.getElementById('clearJobFilters'));const savedSearchPanel=document.createElement('div');savedSearchPanel.className='job-alert-controls';savedSearchPanel.id='savedSearchPanel';savedSearchPanel.innerHTML='<div><strong>Job alerts</strong><small>Save these trade and radius filters to get notified about new matches near your marketplace location.</small></div><button class="button button-orange" id="saveCurrentSearch" type="button">Save this search</button><div class="saved-search-list" id="savedSearchList"></div>';jobFilters.appendChild(savedSearchPanel);document.getElementById('jobRadiusFilter').oninput=()=>renderJobMarketplace();
const reviewDialog=document.createElement('dialog');reviewDialog.className='modal modal-small review-modal';reviewDialog.innerHTML='<button class="modal-close" type="button" data-close-review>&times;</button><div class="modal-heading"><span class="kicker">Verified project review</span><h2 id="reviewTitle">Review your project partner</h2><p>Only companies from this completed awarded job can submit a review.</p></div><form id="reviewForm"><input name="jobId" type="hidden"><div class="review-rating-grid"><label><span>Quality</span><select name="qualityRating" required><option value="5">5 - Excellent</option><option value="4">4 - Very good</option><option value="3">3 - Good</option><option value="2">2 - Needs improvement</option><option value="1">1 - Poor</option></select></label><label><span>Schedule</span><select name="scheduleRating" required><option value="5">5 - Excellent</option><option value="4">4 - Very good</option><option value="3">3 - Good</option><option value="2">2 - Needs improvement</option><option value="1">1 - Poor</option></select></label><label><span>Communication</span><select name="communicationRating" required><option value="5">5 - Excellent</option><option value="4">4 - Very good</option><option value="3">3 - Good</option><option value="2">2 - Needs improvement</option><option value="1">1 - Poor</option></select></label><label><span>Professionalism</span><select name="professionalismRating" required><option value="5">5 - Excellent</option><option value="4">4 - Very good</option><option value="3">3 - Good</option><option value="2">2 - Needs improvement</option><option value="1">1 - Poor</option></select></label></div><label class="recommend-check"><input name="recommends" type="checkbox" checked><span>I recommend this company</span></label><label><span>Written review</span><textarea name="body" rows="4" placeholder="What should other companies know?"></textarea></label><button class="button button-orange button-full" type="submit">Publish verified review</button></form>';document.body.appendChild(reviewDialog);
let savedSearches=[],projectReviewState={};
function routeToView(path){const map={'/jobs':'jobs','/calendar':'calendar','/profile':'profile','/network':'network','/messages':'messages'};switchView(map[path]||'overview')}
async function loadNotifications(){try{const result=await api('/api/notifications');document.getElementById('notificationCount').textContent=result.unread||'';document.getElementById('notificationList').innerHTML=result.notifications.length?result.notifications.map(item=>`<button class="notification-item ${item.readAt?'':'unread'}" type="button" data-notification="${item.id}" data-path="${escapeHtml(item.path)}"><span class="notification-dot"></span><div><strong>${escapeHtml(item.title)}</strong><p>${escapeHtml(item.message)}</p><small>${new Date(item.createdAt).toLocaleString()}</small></div></button>`).join(''):'<div class="list-empty">You are all caught up.</div>';document.querySelectorAll('[data-notification]').forEach(button=>button.onclick=async()=>{await api(`/api/notifications/${button.dataset.notification}/read`,{method:'POST'});await loadNotifications();routeToView(button.dataset.path)})}catch(error){showNotice(error.message,true)}}
async function loadSavedSearches(){if(!dashboard?.company.capabilities.includes('subcontractor')){savedSearchPanel.hidden=true;radiusLabel.hidden=true;return}savedSearchPanel.hidden=false;radiusLabel.hidden=false;const radius=document.getElementById('jobRadiusFilter');if(!radius.dataset.ready){radius.value=String(dashboard.company.serviceRadius||50);radius.dataset.ready='true';renderJobMarketplace()}try{const result=await api('/api/saved-searches');savedSearches=result.savedSearches;document.getElementById('savedSearchList').innerHTML=savedSearches.length?savedSearches.map(search=>`<span><strong>${escapeHtml(search.name)}</strong><small>${escapeHtml(search.trade||'All trades')} · ${search.radiusMiles} miles</small><button type="button" aria-label="Delete ${escapeHtml(search.name)}" data-delete-search="${search.id}">&times;</button></span>`).join(''):'<small>No saved job alerts yet.</small>';document.querySelectorAll('[data-delete-search]').forEach(button=>button.onclick=async()=>{await api(`/api/saved-searches/${button.dataset.deleteSearch}`,{method:'DELETE'});loadSavedSearches()})}catch(error){showNotice(error.message,true)}}
function addServiceRadius(){const panel=document.getElementById('locationSettings');if(!panel||panel.querySelector('#serviceRadiusForm')||!dashboard)return;const form=document.createElement('form');form.id='serviceRadiusForm';form.className='service-radius-form';form.innerHTML=`<label><span>Travel radius</span><select name="serviceRadius"><option value="25">25 miles</option><option value="50">50 miles</option><option value="75">75 miles</option><option value="100">100 miles</option><option value="150">150 miles</option><option value="250">250 miles</option></select></label><button class="button button-dark" type="submit">Update radius</button>`;form.elements.serviceRadius.value=String(dashboard.company.serviceRadius||50);panel.appendChild(form);form.onsubmit=async event=>{event.preventDefault();try{await api('/api/profile/service-area',{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(form)))});await refresh();showNotice('Travel radius updated. Marketplace matches have been refreshed.')}catch(error){showNotice(error.message,true)}}}
async function enhanceProjects(){const root=document.getElementById('upcomingJobs');if(!root||!dashboard)return;const events=(await api('/api/calendar')).events;await Promise.all(events.map(async event=>{try{projectReviewState[event.id]=(await api(`/api/jobs/${event.id}/reviews`)).reviews}catch{projectReviewState[event.id]=[]}}));events.forEach(event=>{const card=document.getElementById(`calendar-${event.id}`);if(!card||card.querySelector('.project-workflow-actions'))return;const reviewed=projectReviewState[event.id].some(review=>review.reviewerCompanyId===dashboard.company.id),actions=document.createElement('div');actions.className='project-workflow-actions';if(event.status==='awarded'&&event.postingCompanyId===dashboard.company.id)actions.innerHTML+='<button class="button button-orange" type="button" data-complete-job="'+event.id+'">Mark project complete</button>';if(event.status==='completed'&&!reviewed)actions.innerHTML+='<button class="button button-dark" type="button" data-review-job="'+event.id+'" data-partner="'+escapeHtml(event.partnerCompany.name)+'">Leave verified review</button>';if(event.status==='completed'&&reviewed)actions.innerHTML+='<span class="connection-status accepted">Review submitted</span>';card.appendChild(actions)});document.querySelectorAll('[data-complete-job]').forEach(button=>button.onclick=async()=>{try{await api(`/api/jobs/${button.dataset.completeJob}/complete`,{method:'POST'});await refresh();await loadCalendar();await enhanceProjects();showNotice('Project completed. Verified reviews are now unlocked for both parties.')}catch(error){showNotice(error.message,true)}});document.querySelectorAll('[data-review-job]').forEach(button=>button.onclick=()=>{reviewDialog.querySelector('[name="jobId"]').value=button.dataset.reviewJob;document.getElementById('reviewTitle').textContent=`Review ${button.dataset.partner}`;reviewDialog.showModal()})}
notificationButton.onclick=()=>{switchView('notifications');loadNotifications()};document.getElementById('readAllNotifications').onclick=async()=>{await api('/api/notifications/read-all',{method:'POST'});loadNotifications()};document.getElementById('saveCurrentSearch').onclick=async()=>{const trade=document.getElementById('jobTradeFilter').value,radiusMiles=document.getElementById('jobRadiusFilter').value;try{await api('/api/saved-searches',{method:'POST',body:JSON.stringify({trade,radiusMiles})});await loadSavedSearches();showNotice('These Find Jobs filters are now saved as a job alert.')}catch(error){showNotice(error.message,true)}};document.querySelector('[data-close-review]').onclick=()=>reviewDialog.close();document.getElementById('reviewForm').onsubmit=async event=>{event.preventDefault();const data=Object.fromEntries(new FormData(event.currentTarget)),jobId=data.jobId;data.recommends=event.currentTarget.elements.recommends.checked;delete data.jobId;try{await api(`/api/jobs/${jobId}/reviews`,{method:'POST',body:JSON.stringify(data)});reviewDialog.close();await enhanceProjects();showNotice('Verified review published.')}catch(error){showNotice(error.message,true)}};
new MutationObserver(()=>{addServiceRadius();if(!document.querySelector('.project-workflow-actions'))enhanceProjects()}).observe(document.body,{childList:true,subtree:true});const marketplaceRefresh=refresh;refresh=async function(){await marketplaceRefresh();document.getElementById('notificationCount').textContent=dashboard.unreadNotifications||'';addServiceRadius();loadSavedSearches()};const marketplaceWait=setInterval(()=>{if(dashboard){clearInterval(marketplaceWait);document.getElementById('notificationCount').textContent=dashboard.unreadNotifications||'';addServiceRadius();loadSavedSearches();loadNotifications();enhanceProjects()}},100);setTimeout(()=>clearInterval(marketplaceWait),10000);if(location.pathname==='/notifications'){switchView('notifications');loadNotifications()}
